1	"use client";
2	
3	import { useEffect, useRef, type PointerEvent as ReactPointerEvent } from "react";
4	import { RenderingEngine, worldBounds, type IRenderBackend } from "@motion-studio/rendering";
5	import type { IFrameState } from "@motion-studio/shared";
6	import { useEditorKernel } from "../editor-kernel-provider";
7	import { useCanvasStore } from "../../state/use-canvas-store";
8	import { useTimelineStore } from "../../state/use-timeline-store";
9	import { useEngineRevisionStore } from "../../state/use-engine-revision-store";
10	import { createRenderBackend } from "../../editor-kernel/render-backend-factory";
11	import { buildFrameState } from "../../editor-kernel/frame-state-builder";
12	
13	/**
14	 * Hosts the real `RenderingEngine`/`IRenderBackend` pipeline
15	 * (`ARCHITECTURE.md` §4 Frame State → pixels) against an actual
16	 * `<canvas>`. `RenderingEngine`'s lifecycle is owned here, not by
17	 * `AppEngine` — it needs the real canvas element, which only exists once
18	 * this component mounts (see `EditorKernel`'s doc comment). Content is
19	 * placeholder colored rects (`placeholder-color.ts`) regardless of which
20	 * backend wins the fallback chain — no decoder pipeline exists anywhere in
21	 * the project yet.
22	 */
23	export function CanvasPanel(): JSX.Element {
24	  const kernel = useEditorKernel();
25	  const canvasRef = useRef<HTMLCanvasElement>(null);
26	  const overlayRef = useRef<HTMLCanvasElement>(null);
27	  const renderingEngineRef = useRef<RenderingEngine | null>(null);
28	  const backendRef = useRef<IRenderBackend | null>(null);
29	  const lastFrameStateRef = useRef<IFrameState | null>(null);
30	  const revision = useEngineRevisionStore((state) => state.revision);
31	  const selection = useTimelineStore((state) => state.selection);
32	  const select = useTimelineStore((state) => state.select);
33	  const showOverlays = useCanvasStore((state) => state.showOverlays);
34	
35	  const composition = kernel.timelineEngine.requireComposition(kernel.defaultCompositionId);
36	
37	  const renderCurrentFrame = (): void => {
38	    const engine = renderingEngineRef.current;
39	    if (!engine) {
40	      return;
41	    }
42	    const frameState = buildFrameState(
43	      kernel.playback.currentTick,
44	      kernel.defaultCompositionId,
45	      kernel.timelineEngine,
46	      kernel.layerEngine,
47	      kernel.animationEngine,
48	    );
49	    lastFrameStateRef.current = frameState;
50	    void engine.renderFrame(frameState);
51	    drawOverlay(frameState);
52	  };
53	
54	  const drawOverlay = (frameState: IFrameState): void => {
55	    const overlay = overlayRef.current;
56	    const ctx = overlay?.getContext("2d");
57	    if (!overlay || !ctx) {
58	      return;
59	    }
60	    ctx.clearRect(0, 0, overlay.width, overlay.height);
61	    if (!showOverlays) {
62	      return;
63	    }
64	    ctx.strokeStyle = "#5b8cff";
65	    ctx.lineWidth = 2;
66	    for (const layer of frameState.layers) {
67	      if (!selection.layerIds.includes(layer.layerId)) {
68	        continue;
69	      }
70	      const box = worldBounds(layer.bounds, layer.transform);
71	      ctx.strokeRect(box.x, box.y, box.width, box.height);
72	    }
73	  };
74	
75	  useEffect(() => {
76	    let cancelled = false;
77	
78	    createRenderBackend(canvasRef.current!)
79	      .then(async (backend) => {
80	        if (cancelled) {
81	          await backend.dispose();
82	          return;
83	        }
84	        backendRef.current = backend;
85	        const engine = new RenderingEngine(backend);
86	        await engine.setTarget({ width: composition.width, height: composition.height });
87	        renderingEngineRef.current = engine;
88	        renderCurrentFrame();
89	      })
90	      .catch((error: unknown) => {
91	        console.error("CanvasPanel: failed to create render backend", error);
92	      });
93	
94	    return () => {
95	      cancelled = true;
96	      void renderingEngineRef.current?.dispose();
97	      renderingEngineRef.current = null;
98	      backendRef.current = null;
99	    };
100	  }, [kernel]);
101	
102	  // Re-subscribes on every dependency change so the tick listener's closure
103	  // never reads stale `selection`/`showOverlays` — cheap, since subscribing
104	  // is just a Set add/remove, and it also repaints immediately (covers a
105	  // Command executing, selection changing, or overlay toggle while paused).
106	  useEffect(() => {
107	    renderCurrentFrame();
108	    return kernel.playback.onTick(() => renderCurrentFrame());
109	  }, [kernel, revision, selection, showOverlays]);
110	
111	  const handlePointerDown = (event: ReactPointerEvent<HTMLCanvasElement>): void => {
112	    const frameState = lastFrameStateRef.current;
113	    const canvas = overlayRef.current;
114	    if (!frameState || !canvas) {
115	      return;
116	    }
117	    const rect = canvas.getBoundingClientRect();
118	    const scaleX = canvas.width / rect.width;
