1	"use client";
2	
3	import { useEffect } from "react";
4	import { DndContext, PointerSensor, useSensor, useSensors, type DragEndEvent } from "@dnd-kit/core";
5	import {
6	  PlaybackState,
7	  secondsToTicks,
8	  toTick,
9	  type AssetId,
10	  type AssetType,
11	  type TrackId,
12	  type TrackItemId,
13	} from "@motion-studio/shared";
14	import { useEditorKernel } from "./editor-kernel-provider";
15	import { ToolbarPanel } from "./toolbar/toolbar-panel";
16	import { CanvasPanel } from "./canvas/canvas-panel";
17	import { TimelinePanel } from "./timeline/timeline-panel";
18	import { InspectorPanel } from "./inspector/inspector-panel";
19	import { AssetBrowserPanel } from "./asset-browser/asset-browser-panel";
20	import { useTimelineStore } from "../state/use-timeline-store";
21	import { useCanvasStore } from "../state/use-canvas-store";
22	import type { EditorKernel } from "../editor-kernel/editor-kernel";
23	
24	const DEFAULT_CLIP_DURATION_SECONDS = 3;
25	
26	type DragData =
27	  | { type: "asset"; assetId: AssetId; assetType: AssetType; name: string }
28	  | { type: "clip"; trackItemId: TrackItemId };
29	
30	type DropData = { type: "track"; trackId: TrackId };
31	
32	/**
33	 * Handles both drop targets a Timeline track accepts: a freshly dragged
34	 * Asset Browser tile (creates a Layer + TrackItem via
35	 * `TimelineEditorService.addClipFromAsset`) and an existing clip being
36	 * repositioned (`moveTrackItem`). One `DndContext` at the shell level so
37	 * both the Asset Browser and Timeline panels can participate without each
38	 * owning a separate drag pipeline (`toolbar.md`: "Canvas/Timeline UI ...
39	 * should consume this one pipeline, not each define their own").
40	 */
41	function handleDragEnd(kernel: EditorKernel, event: DragEndEvent): void {
42	  const overData = event.over?.data.current as DropData | undefined;
43	  const activeData = event.active.data.current as DragData | undefined;
44	  if (!overData || overData.type !== "track" || !activeData) {
45	    return;
46	  }
47	  const ticksPerPixel = useTimelineStore.getState().zoomTicksPerPixel;
48	
49	  if (activeData.type === "asset") {
50	    const activeRect = event.active.rect.current.translated;
51	    const overRect = event.over?.rect;
52	    const pixelOffset = activeRect && overRect ? Math.max(0, activeRect.left - overRect.left) : 0;
53	    const composition = kernel.timelineEngine.requireComposition(kernel.defaultCompositionId);
54	    kernel.timelineEditor.addClipFromAsset({
55	      type: "AddClipFromAsset",
56	      payload: {
57	        trackId: overData.trackId,
58	        assetId: activeData.assetId,
59	        assetType: activeData.assetType,
60	        name: activeData.name,
61	        startTick: toTick(pixelOffset * ticksPerPixel),
62	        durationTicks: secondsToTicks(DEFAULT_CLIP_DURATION_SECONDS, composition.fps),
63	      },
64	    });
65	    return;
66	  }
67	
68	  const trackItem = kernel.timelineEngine.requireTrackItem(activeData.trackItemId);
69	  const deltaTicks = toTick(event.delta.x * ticksPerPixel);
70	  const toStartTick = toTick(Math.max(0, trackItem.startTick + deltaTicks));
71	  // A plain click still fires `onDragEnd` with zero (or near-zero) movement
72	  // — the `PointerSensor` activation distance below filters out most of
73	  // these, but this guard is a cheap, load-bearing backstop: without it, a
74	  // no-op move gets pushed onto the undo stack on every click, and Undo
75	  // then reverts that no-op instead of whatever the user actually meant.
76	  if (overData.trackId === trackItem.trackId && toStartTick === trackItem.startTick) {
77	    return;
78	  }
79	  kernel.timelineEditor.moveTrackItem({
80	    type: "MoveTrackItem",
81	    payload: { trackItemId: activeData.trackItemId, toTrackId: overData.trackId, toStartTick },
82	  });
83	}
84	
85	const GLOBAL_BINDINGS = [
86	  { key: "Delete", commandId: "DeleteSelection" },
87	  { key: "Backspace", commandId: "DeleteSelection" },
88	  { key: "Mod+Z", commandId: "Undo" },
89	  { key: "Mod+Shift+Z", commandId: "Redo" },
90	  { key: " ", commandId: "TogglePlayback" },
91	  { key: "V", commandId: "ActivateSelectTool" },
92	] as const;
93	
94	function dispatchShortcutCommand(kernel: EditorKernel, commandId: string): void {
95	  switch (commandId) {
96	    case "DeleteSelection": {
97	      const { selection, clearSelection } = useTimelineStore.getState();
98	      kernel.timelineEditor.deleteSelection({
99	        type: "DeleteSelection",
100	        payload: { trackItemIds: selection.trackItemIds },
101	      });
102	      clearSelection();
103	      return;
104	    }
105	    case "Undo":
106	      if (kernel.commandBus.canUndo) {
107	        kernel.commandBus.undo();
108	      }
109	      return;
110	    case "Redo":
111	      if (kernel.commandBus.canRedo) {
112	        kernel.commandBus.redo();
113	      }
114	      return;
115	    case "TogglePlayback":
116	      if (kernel.playback.playbackState === PlaybackState.Playing) {
117	        kernel.playback.pause();
118	      } else {
119	        kernel.playback.play();
120	      }
121	      return;
122	    case "ActivateSelectTool":
123	      kernel.toolRegistry.activate("select");
124	      useCanvasStore.getState().setActiveTool("select");
125	      return;
126	    default:
127	      return;
128	  }
129	}
130	
131	function isEditableTarget(target: EventTarget | null): boolean {
132	  if (!(target instanceof HTMLElement)) {
133	    return false;
134	  }
135	  return target.tagName === "INPUT" || target.tagName === "TEXTAREA" || target.isContentEditable;
136	}
137	
138	/**
139	 * Fixed CSS grid — Toolbar, Timeline, Inspector, Asset Browser, Canvas each
140	 * in a static cell. No dockable Split/Stack/Panel tree, no floating panels,
141	 * no layout-undo (ADR-011) — `docs/17-ui/docking.md`'s real engine is
142	 * deferred to its own future pass (Phase 15 scope decision).
143	 */
144	export function EditorShell(): JSX.Element {
145	  const kernel = useEditorKernel();
146	  // Without an activation distance, `PointerSensor` starts a drag on the
147	  // very first pointermove, which swallows the click a plain selection tap
148	  // on a clip/asset tile needs — 4px matches dnd-kit's own recommended
149	  // default for this exact click-vs-drag ambiguity.
150	  const sensors = useSensors(useSensor(PointerSensor, { activationConstraint: { distance: 4 } }));
151	
152	  useEffect(() => {
153	    for (const binding of GLOBAL_BINDINGS) {
154	      kernel.shortcuts.register({
155	        key: binding.key,
156	        commandId: binding.commandId,
157	        scope: "Global",
158	      });
159	    }
160	
161	    const handleKeyDown = (event: KeyboardEvent): void => {
162	      if (isEditableTarget(event.target)) {
163	        return;
164	      }
165	      const commandId = kernel.shortcuts.resolve(event);
166	      if (!commandId) {
167	        return;
168	      }
169	      event.preventDefault();
170	      dispatchShortcutCommand(kernel, commandId);
171	    };
172	
173	    window.addEventListener("keydown", handleKeyDown);
174	    return () => {
175	      window.removeEventListener("keydown", handleKeyDown);
176	      for (const binding of GLOBAL_BINDINGS) {
177	        kernel.shortcuts.unregister(binding.key, "Global");
178	      }
179	    };
180	  }, [kernel]);
181	
182	  return (
183	    <DndContext sensors={sensors} onDragEnd={(event) => handleDragEnd(kernel, event)}>
184	      <div className="grid h-screen grid-rows-[auto_1fr_260px] bg-editor-bg text-editor-text">
185	        <ToolbarPanel />
186	        <div className="grid grid-cols-[240px_1fr_280px] overflow-hidden">
187	          <AssetBrowserPanel />
188	          <CanvasPanel />
189	          <InspectorPanel />
190	        </div>
191	        <TimelinePanel />
192	      </div>
193	    </DndContext>
194	  );
195	}
