28	/**
29	 * Assembles the 8 engines this phase's panels touch (Storage, Assets,
30	 * Layer, Timeline, Animation, History, Plugin, and — via `toolRegistry` —
31	 * the plugin-facing half of what would become a Tool Registry) into one
32	 * running `AppEngine`, plus the Command Bus/Editor Services on top. This is
33	 * the integration layer every phase since 7 flagged as not existing yet.
34	 * Audio/Export/AI/Effects are out of scope this phase (no panel needs
35	 * them) — see `EditorKernel`'s doc comment.
36	 *
37	 * Browser-only (opens real IndexedDB/OPFS) — must only run from a Client
38	 * Component, never during Next.js SSR.
39	 */
40	export async function createEditorKernel(): Promise<EditorKernel> {
41	  const appEngine = new AppEngine();
42	
43	  const storageEngine = new StorageEngine();
44	  const blobStore = new AssetBlobStore(storageEngine);
45	  const catalog = new AssetCatalog(new AssetCatalogRepository(storageEngine));
46	  const assetManager = new AssetManager({
47	    blobStore,
48	    catalog,
49	    metadataExtractor: browserMetadataExtractor,
50	    events: appEngine.events,
51	  });
52	
53	  const layerEngine = new LayerEngine();
54	  const timelineEngine = new TimelineEngine();
55	  const animationEngine = new AnimationEngine();
56	  const historyEngine = new HistoryEngine({ events: appEngine.events });
57	
58	  const toolRegistry = new ToolRegistry();
59	  const pluginEngine = new PluginEngine({
60	    hostApi: {
61	      effects: undefined,
62	      export: undefined,
63	      ai: undefined,
64	      tools: toolRegistry,
65	      panels: undefined,
66	    },
67	    events: appEngine.events,
68	  });
69	
70	  appEngine.registerEngine(storageEngine);
71	  appEngine.registerEngine(assetManager);
72	  appEngine.registerEngine(layerEngine);
73	  appEngine.registerEngine(timelineEngine);
74	  appEngine.registerEngine(animationEngine);
75	  appEngine.registerEngine(historyEngine);
76	  appEngine.registerEngine(pluginEngine);
77	
78	  await appEngine.start();
79	
80	  seedDefaultComposition(timelineEngine);
81	
82	  pluginEngine.register(createSelectToolPlugin(), SELECT_TOOL_PLUGIN_MANIFEST);
83	  await pluginEngine.activate(SELECT_TOOL_PLUGIN_MANIFEST.id);
84	  toolRegistry.activate("select");
85	
86	  return new EditorKernel(
87	    appEngine,
88	    storageEngine,
89	    assetManager,
90	    layerEngine,
91	    timelineEngine,
92	    animationEngine,
93	    historyEngine,
94	    pluginEngine,
95	    toolRegistry,
96	    DEFAULT_COMPOSITION_ID,
97	  );
98	}
