101	 * No Project Service/persistence exists yet (out of this phase's scope,
102	 * same gap `docs/04-core/core-overview.md` flags for `AppEngine`), so this
103	 * seeds one Composition with a video and an audio Track — just enough for
104	 * the vertical slice's "import a clip → drop it on the Timeline" flow to
105	 * have somewhere to go. Not dispatched through the Command Bus: this is
106	 * initial engine state, not a user-undoable edit.
107	 */
108	function seedDefaultComposition(timelineEngine: TimelineEngine): void {
109	  const composition = createComposition({
110	    id: DEFAULT_COMPOSITION_ID,
111	    name: "Untitled Composition",
112	    width: 1920,
113	    height: 1080,
114	    fps: DEFAULT_FPS,
115	    durationTicks: secondsToTicks(DEFAULT_DURATION_SECONDS, DEFAULT_FPS),
116	  });
117	  timelineEngine.compositions.add(composition);
118	
119	  timelineEngine.addTrack(
120	    composition.id,
121	    createTrack({ id: createTrackId("v1"), type: TrackType.Video, label: "V1" }),
122	  );
123	  timelineEngine.addTrack(
124	    composition.id,
125	    createTrack({ id: createTrackId("a1"), type: TrackType.Audio, label: "A1" }),
126	  );
