2	
3	/**
4	 * World-space axis-aligned bounding box of `bounds` (in the layer's local
5	 * space) after applying `transform`: anchor, scale, rotation, then
6	 * translate — the standard 2D layer transform order used throughout the
7	 * Layer/Timeline/Animation engines (`ITransform2D`, `08-layer-engine/`).
8	 * Rotation makes the result an AABB around the rotated corners, not a
9	 * rotated rect — sufficient for culling/dirty-rect purposes.
10	 */
11	export function worldBounds(bounds: IBounds, transform: ITransform2D): IBounds {
12	  const localCorners: Array<[number, number]> = [
